```{.r .cell-code}
st_kde <- spattemp.density(
  pp     = biz_ppp_clip,                         
  tt     = t_num,                                
  tlim   = range(t_num, na.rm = TRUE),           
  h      = 800,                                  
  lambda = 30                                    
)

summary(st_kde)
```

